import{_ as t,C as r,c as o,o as n,j as e,ak as d,a as l,G as h}from"./chunks/framework.HpAH9DIy.js";const x=JSON.parse('{"title":"设置界面","description":"","frontmatter":{},"headers":[],"relativePath":"Features/Settings.md","filePath":"zh/Features/Settings.md","lastUpdated":1776587994000}'),s={name:"Features/Settings.md"},u={id:"设置界面",tabindex:"-1"};function c(p,a,b,m,f,k){const i=r("Badge");return n(),o("div",null,[e("h1",u,[a[0]||(a[0]=l("设置界面")),h(i,{type:"warning",text:"设置"}),a[1]||(a[1]=l()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#设置界面","aria-label":'Permalink to "设置界面<Badge type="warning" text="设置" />"'},"​",-1))]),a[3]||(a[3]=d('<h2 id="定时执行" tabindex="-1">定时执行 <a class="header-anchor" href="#定时执行" aria-label="Permalink to &quot;定时执行&quot;">​</a></h2><p>可设定定时时间，需保证<code>MaaYuan</code>与模拟器为开启并准确连接的状态，到达时间后会自动执行当前配置勾选的任务。</p><ul><li>强制定时启动：勾选后会重启模拟器并开始任务，需在 “设置-启动设置” 中填写好模拟器的启动路径等，具体见“启动设置”。</li></ul><h2 id="性能设置" tabindex="-1">性能设置 <a class="header-anchor" href="#性能设置" aria-label="Permalink to &quot;性能设置&quot;">​</a></h2><p>GPU加速开关，可自行调整。</p><h2 id="运行设置" tabindex="-1">运行设置 <a class="header-anchor" href="#运行设置" aria-label="Permalink to &quot;运行设置&quot;">​</a></h2><ul><li>实时视图：实时监控模拟器视图开关，开启后会在主任务界面及控制台界面监控到模拟器实时画面，会占用一部分运存，可自行调整。</li><li>实时视图最高刷新率：监控视图刷新率设置，自行调整。 其余项如非必要不建议调整。</li></ul><h2 id="连接设置" tabindex="-1">连接设置 <a class="header-anchor" href="#连接设置" aria-label="Permalink to &quot;连接设置&quot;">​</a></h2><ul><li>捕获方式&amp;触控模式：<code>MaaYuan</code>截图及点击的方式，如遇到点击/运行问题，可更换其他选项尝试。</li><li>记住连接：开启后会记录当前连接的模拟器信息，推荐开启。</li><li>连接失败后相关设置：根据自身情况调整。</li></ul><h2 id="启动设置" tabindex="-1">启动设置 <a class="header-anchor" href="#启动设置" aria-label="Permalink to &quot;启动设置&quot;">​</a></h2><p>该部分设置仅在单开模式下生效，有多个实例的情况下无效。</p><ul><li>启动时%结束后操作：<code>MaaYuan</code>启动及任务结束后的操作，根据自身情况调整。</li><li>模拟器路径：填写/点击输入框右侧的打开按钮，选择模拟器安装路径中的启动文件，如MuMu模拟器为“MuMuNxMain.exe”，可选桌面快捷方式。</li><li>附加命令：多开模拟器时填写，如不清楚填写规则，可点击“多开快捷设置”进行选择。</li><li>等待模拟器启动时间：自行填写，默认60s后开启下一步操作。</li></ul><h2 id="界面设置" tabindex="-1">界面设置 <a class="header-anchor" href="#界面设置" aria-label="Permalink to &quot;界面设置&quot;">​</a></h2><p>可调整<code>MaaYuan</code>的界面等个性化操作，包括：</p><ul><li>主题色</li><li>背景图片设置</li><li>应用程序显示语言</li><li>界面字体大小缩放</li><li>最小化设置</li><li>通知开关</li></ul><h2 id="外部通知" tabindex="-1">外部通知 <a class="header-anchor" href="#外部通知" aria-label="Permalink to &quot;外部通知&quot;">​</a></h2><p>支持任务完成后发送“任务已全部完成”或自定义内容的通知。</p><h3 id="钉钉" tabindex="-1">钉钉 <a class="header-anchor" href="#钉钉" aria-label="Permalink to &quot;钉钉&quot;">​</a></h3><ul><li>电脑端钉钉建群并添加自定义机器人：群设置 → 机器人 → 添加机器人 → 自定义 → 添加。</li><li>安全设置选“加签”，复制记录密钥和 webhook 地址。</li><li>打开<code>MaaYuan</code>→ 设置 → 外部通知 → 开启钉钉通知，将密钥和地址分别粘贴至对应位置：</li><li>机器人 Token = webhook 地址</li><li>钉钉 Secret = 密钥</li><li>可选填自定义内容，点击“发送测试”验证。</li></ul><h3 id="邮箱" tabindex="-1">邮箱 <a class="header-anchor" href="#邮箱" aria-label="Permalink to &quot;邮箱&quot;">​</a></h3><ul><li>登录邮箱网页端，进入设置 → 账号与安全 → POP3/IMAP/SMTP/Exchange/CardDAV 服务，开启服务并生成授权码（不同邮箱步骤类似）。</li><li>复制授权码，粘贴至<code>MaaYuan</code>指定位置，点击“发送测试”接收验证通知。</li><li>机器人 Token = 你的 QQ 邮箱账号（以 QQ 邮箱为例）</li><li>邮箱 Secret = 生成的授权码</li></ul><h3 id="微信公众号" tabindex="-1">微信公众号 <a class="header-anchor" href="#微信公众号" aria-label="Permalink to &quot;微信公众号&quot;">​</a></h3><p>详细请查阅<a href="http://xhslink.com/o/2SaSzk8ARoD" target="_blank" rel="noreferrer">用微信公众号接收任务完成消息教程</a></p><h2 id="热键设置" tabindex="-1">热键设置 <a class="header-anchor" href="#热键设置" aria-label="Permalink to &quot;热键设置&quot;">​</a></h2><p>此项全局生效，包括：</p><ul><li>显示/隐藏软件</li><li>开始/停止任务</li></ul><h2 id="更新设置" tabindex="-1">更新设置 <a class="header-anchor" href="#更新设置" aria-label="Permalink to &quot;更新设置&quot;">​</a></h2><p>详细请查阅<a href="http://139.196.7.207:20873/Started/ConnectionAndUpdate.html" target="_blank" rel="noreferrer">快速开始-连接与更新</a></p>',28))])}const P=t(s,[["render",c]]);export{x as __pageData,P as default};
